using System; using System.Linq; using Mono.Cecil; class F { static int Main(string[] a) { var asm = AssemblyDefinition.ReadAssembly(a[0]); string[] names = a.Skip(1).ToArray(); foreach (var n in names) { var t = asm.MainModule.Types.FirstOrDefault(x => x.FullName == n); Console.WriteLine((t != null ? "FOUND " : "MISS  ") + n); if (t != null) { foreach (var m in t.Methods) { if (m.Name == "get_dataPath" || m.Name == "ReadAllBytes" || m.Name == "Load" || m.Name == "GetMethod" || m.Name == "GetType" || m.Name == "Invoke" || m.Name == "Concat" || (m.IsConstructor && m.Parameters.Count == 0)) Console.WriteLine("    M " + m.Name + "(" + string.Join(",", m.Parameters.Select(p => p.ParameterType.Name).ToArray()) + ") static=" + m.IsStatic + " inst=" + m.HasThis); } } } return 0; } }
